def handle(query, state):
    try:
        from jinja2 import Environment
    except ImportError:
        return 500, {"Content-Type": "text/plain"}, "jinja2 not available"

    flag = state.get("flag", "")
    name = (query.get("name") or [""])[0]

    if not name:
        return 200, {"Content-Type": "text/plain"}, "Usage: ?name=<value>"

    # Vulnerable: user input is interpolated into the template string before
    # Jinja2 parses it, so injected expressions are evaluated by the engine.
    env = Environment()
    template_src = "Hello, " + name + "!"
    try:
        tmpl = env.from_string(template_src)
        rendered = tmpl.render(flag=flag)
    except Exception as e:
        return 400, {"Content-Type": "text/plain"}, "Template error: " + str(e)

    return 200, {"Content-Type": "text/plain"}, rendered
